  "headline": "Caspofungin acetate is not on FDA's shortage list as of 2026-10-21",
  "headline_cites": ["D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include caspofungin acetate as of 2026-10-21.",
      "cites": ["D2"]
    },
    {
      "text": "Two manufacturers, Fresenius Kabi USA, LLC and Jiangsu Hengrui Pharmaceuticals Co., have posted discontinuations on the FDA list with initial posting dates of 2026-01-12 and 2026-06-30 respectively.",
      "cites": ["E3", "E4"]
    },
    {
      "text": "Corvale General currently holds 326 vials of the 7 mg/mL, 10.8 mL presentation, providing 20.2 days of supply at the current usage rate.",
      "cites": ["D1"]
    },
    {
      "text": "The rule-based recommendation is to buy from Fosun Pharma USA Inc., which is not on the FDA shortage list today.",
      "cites": ["D3"]
    },
    {
      "text": "Alternative manufacturers Gland Pharma Limited and Merck Sharp & Dohme LLC are also not on the FDA shortage list today.",
      "cites": ["D4", "D5"]
    }
  ]
}
